fn min_steps(x: i8) -> i8 {
    // For x >= 1, the minimal s such that 5*s >= x is ceil(x/5).
    // For positive x, ceil(x/5) == ((x - 1) / 5) + 1 because integer
    // division truncates toward zero.
    ((x - 1) / 5) + 1
}

